<?php
declare(strict_types=1);
namespace BYPCMS\Core;
require_once __DIR__.'/Content.php';
require_once __DIR__.'/Journal.php';

/** Chronicle uses Content records, permissions and native routes; only presentation is specific. */
final class Chronicle {
    private static function text(array $query,string $key,int $limit=120):string {
        return is_scalar($query[$key]??'')?mb_substr(trim((string)($query[$key]??'')),0,$limit):'';
    }
    private static function published(array $page):bool {
        $status=$page['status']??'published';$date=$page['published_at']??'';
        return in_array($status,['published','scheduled'],true)&&($date!==''?strtotime($date.' UTC')!==false&&strtotime($date.' UTC')<=time():$status==='published');
    }
    public static function date(string $value):string {return $value&&strtotime($value)!==false?Journal::date($value):'Без даты';}
    public static function feed(array $pages,array $settings,string $base=''):void {
        header('Content-Type: application/rss+xml; charset=utf-8');
        $e=static fn($s)=>htmlspecialchars((string)$s,ENT_XML1|ENT_QUOTES,'UTF-8');$site=rtrim(Content::url($settings['site_url']??''),'/').$base;
        echo '<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>'.$e($settings['site_name']??'Chronicle').'</title><link>'.$e($site.'/').'</link><description>'.$e($settings['tagline']??'').'</description><language>ru</language>';
        $rows=array_values(array_filter($pages,fn($p)=>($p['kind']??'page')==='article'&&self::published($p)));
        usort($rows,fn($a,$b)=>strcmp($b['published_at']??'',$a['published_at']??''));
        foreach(array_slice($rows,0,30)as $p){$url=$site.'/'.trim($p['slug'],'/').'/';echo '<item><title>'.$e($p['title']).'</title><link>'.$e($url).'</link><guid>'.$e($url).'</guid><description>'.$e($p['excerpt']??'').'</description>';if(!empty($p['published_at'])&&strtotime($p['published_at'])!==false)echo '<pubDate>'.gmdate(DATE_RSS,strtotime($p['published_at'].' UTC')).'</pubDate>';echo '</item>';}
        echo '</channel></rss>';
    }
    public static function render(array $pages,array $terms,array $settings,string $path,string $base='',bool $preview=false,string $snapshot=''):void {
        for($i=1;$i<=8;$i++)Content::$images['/themes/chronicle/assets/editorial-'.$i.'.jpg']=['width'=>1200,'variants'=>array_map(fn($w)=>['path'=>'themes/chronicle/assets/editorial-'.$i.'-'.$w.'.webp','width'=>$w],[480,960,1200])];
        $e=[Content::class,'e'];if(!$preview)$pages=array_values(array_filter($pages,fn($p)=>self::published($p)));$path=trim($path,'/');$q=self::text($_GET,'q',100);$category=self::text($_GET,'category');$sort=self::text($_GET,'sort')==='old'?'old':'new';$year=self::text($_GET,'year',4);$month=self::text($_GET,'month',2);$error='';
        foreach(['q','category','sort','year','month','page']as $key)if(!is_scalar($_GET[$key]??''))$error='Проверьте параметры поиска и архива.';
        if(($year!==''&&!preg_match('/^(19|20|21)[0-9]{2}$/D',$year))||($month!==''&&(!ctype_digit($month)||(int)$month<1||(int)$month>12)))$error='Укажите корректные год и месяц.';
        $name=trim($settings['site_name']??'')?:'Chronicle';$tagline=$settings['tagline']??'Сначала контекст. Затем выводы.';$site=rtrim(Content::url($settings['site_url']??''),'/');
        $href=static fn(string $p,array $query=[])=>$base.$p.(($query+($snapshot?['snapshot'=>$snapshot]:[]))?'?'.http_build_query($query+($snapshot?['snapshot'=>$snapshot]:[])):'');
        $asset=static fn(string $p)=>Content::asset('/themes/chronicle/'.$p);
        $articles=array_values(array_filter($pages,fn($p)=>($p['kind']??'page')==='article'&&($preview||(self::published($p)))));
        usort($articles,fn($a,$b)=>strcmp($b['published_at']??'',$a['published_at']??'')?:((int)($b['id']??0)<=>(int)($a['id']??0)));
        $cats=array_values(array_filter($terms,fn($t)=>$t['kind']==='category'));$authors=array_values(array_filter($terms,fn($t)=>$t['kind']==='author'));
        $findTerm=static function(string $slug,string $kind)use($terms){foreach($terms as $t)if($t['slug']===$slug&&$t['kind']===$kind)return $t;return null;};
        $hasPage=static function(string $slug)use($pages){foreach($pages as $p)if(($p['kind']??'page')==='page'&&trim($p['slug'],'/')===$slug)return true;return false;};
        $mode=$path===''?'home':($path==='articles'?'listing':($path==='search'?'search':'404'));$page=null;$term=null;$list=$articles;$title=$name;$description=$tagline;
        if(preg_match('#^(category|author)/([a-z0-9-]+)$#D',$path,$m)){$term=$findTerm($m[2],$m[1]);if($term){$mode=$m[1];$list=array_values(array_filter($list,fn($p)=>($p[$m[1]]??'')===$term['slug']));$title=$term['title'];$description=$term['description']??'';}}
        elseif($mode==='404'){foreach($pages as $p)if(trim($p['slug'],'/')===$path&&($preview||self::published($p))){$page=$p;break;}if($page){$mode=($page['kind']??'page')==='article'?'article':'page';$title=($page['seo_title']??'')?:$page['title'];$description=$page['seo_description']??'';if(!$description)$description=$page['excerpt']??'';}}
        if($mode==='category')$category='';
        if($mode==='listing')$title=($_GET['archive']??'')==='1'?'Архив публикаций':'Все материалы';
        if($mode==='search'){$title=$q!==''?'Поиск: '.$q:'Поиск по изданию';$list=array_values(array_filter($list,fn($p)=>$q!==''&&(isset($settings['_search_matches'])?in_array((int)$p['id'],$settings['_search_matches'],true):mb_stripos($p['title'].' '.($p['excerpt']??'').' '.strip_tags($p['content']??''),$q)!==false)));usort($list,fn($a,$b)=>(int)(mb_stripos($b['title'],$q)!==false)<=>(int)(mb_stripos($a['title'],$q)!==false));}
        if(in_array($mode,['listing','category','author','search'],true)){$list=array_values(array_filter($list,fn($p)=>!$error&&($category===''||($p['category']??'')===$category)&&($year===''||substr($p['published_at']??'',0,4)===$year)&&($month===''||substr($p['published_at']??'',5,2)===str_pad($month,2,'0',STR_PAD_LEFT))));if($sort==='old')$list=array_reverse($list);}
        $total=count($list);$pageCount=max(1,(int)ceil($total/9));$num=min($pageCount,max(1,(int)self::text($_GET,'page')));$status=$mode==='404'?404:($error?400:200);
        if($mode==='404'){$title='Страница не найдена';$description='Материал мог сменить адрес. Найдите его через поиск или откройте архив.';}
        $canonical=Content::url($page['canonical']??'')?:$site.$base.'/'.($path?$path.'/':'');if(str_starts_with($canonical,'/'))$canonical=$site.$canonical;
        $canonicalQuery=array_filter(['page'=>$num>1?$num:null,'category'=>$category,'year'=>$year,'month'=>$month,'sort'=>$sort==='old'?'old':null],fn($v)=>$v!==null&&$v!=='');if(in_array($mode,['listing','category','author'],true)&&$canonicalQuery)$canonical.='?'.http_build_query($canonicalQuery);
        $accent=preg_match('/^#[a-f0-9]{6}$/i',$settings['accent']??'')?$settings['accent']:'#a82b24';$logo=Content::imageUrl($settings['logo']??'');$cover=$page['cover']??($articles[0]['cover']??'');$privatePreview=$preview&&$base==='';
        header('Content-Type: text/html; charset=utf-8');http_response_code($status);header("Content-Security-Policy: default-src 'self'; img-src 'self' https: data:; style-src 'self' 'unsafe-inline'; font-src 'self'; script-src 'self'; frame-ancestors 'self'; base-uri 'none'; form-action 'self'");header('X-Content-Type-Options: nosniff');
        if($preview){header('X-Robots-Tag: noindex, nofollow, noarchive');header('Cache-Control: no-store');}
        $highlight=static function(string $text)use($q,$e,$mode){$safe=$e($text);return $mode==='search'&&$q!==''?(preg_replace('/('.preg_quote($e($q),'/').')/iu','<mark>$1</mark>',$safe)??$safe):$safe;};
        $image=static function(array $p,string $sizes='(max-width:760px) calc(100vw - 40px), 500px',bool $eager=false)use($e){$src=Content::imageUrl($p['cover']??'');return $src?'<img src="'.$e(Content::asset($src)).'"'.Content::imageSet($src,$sizes).' width="1200" height="800" alt="'.$e($p['cover_alt']??$p['title']).'" '.($eager?'fetchpriority="high"':'loading="lazy"').' decoding="async">':'<span class="c-no-image" aria-hidden="true">C.</span>';};
        $meta=static function(array $p)use($e,$href,$findTerm){$author=$findTerm($p['author']??'','author');echo '<div class="c-meta">';if($author)echo '<a href="'.$e($href('/author/'.$author['slug'].'/')).'">'.$e($author['title']).'</a>';else echo '<span>Редакция</span>';echo '<time datetime="'.$e(substr($p['published_at']??'',0,10)).'">'.$e(self::date($p['published_at']??'')).'</time></div>';};
        $card=static function(array $p,string $class='')use($e,$href,$findTerm,$image,$meta,$highlight){$cat=$findTerm($p['category']??'','category');echo '<article class="c-card '.$e($class).'"><a class="c-card-image" href="'.$e($href('/'.$p['slug'].'/')).'">'.$image($p).'</a><div class="c-card-copy"><span class="c-kicker">'.$e($cat['title']??'Материал').'</span><h2><a href="'.$e($href('/'.$p['slug'].'/')).'">'.$highlight($p['title']).'</a></h2><p>'.$highlight($p['excerpt']??'').'</p>';$meta($p);echo '</div></article>';};
        $toc=[];$reading='';if($page){$reading=Content::html($page['content']??'').Content::blocks($page['blocks']??[]);$reading=preg_replace_callback('#<h([23])(?: [^>]*)?>(.*?)</h\1>#su',static function($m)use(&$toc){$id='reading-'.(count($toc)+1);$toc[]=['id'=>$id,'title'=>strip_tags(html_entity_decode($m[2],ENT_QUOTES,'UTF-8'))];return '<h'.$m[1].' id="'.$id.'">'.$m[2].'</h'.$m[1].'>';},$reading);}
        $latest=$articles[0]['published_at']??'';$years=array_unique(array_filter(array_map(fn($p)=>substr($p['published_at']??'',0,4),$articles)));if($year!==''&&preg_match('/^(19|20|21)[0-9]{2}$/D',$year)&&!in_array($year,$years,true))$years[]=$year;rsort($years);
        ?>
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $e($title.($mode==='home'?'':' — '.$name)) ?></title><meta name="description" content="<?= $e($description) ?>"><meta name="robots" content="<?= $preview||!empty($page['noindex'])||$mode==='search'||$status!==200?'noindex,follow':'index,follow' ?>"><link rel="canonical" href="<?= $e($canonical) ?>"><meta property="og:type" content="<?= $mode==='article'?'article':'website' ?>"><meta property="og:title" content="<?= $e($title) ?>"><meta property="og:description" content="<?= $e($description) ?>"><meta property="og:url" content="<?= $e($canonical) ?>"><?php if($cover&&!str_starts_with($cover,'data:')): ?><meta property="og:image" content="<?= $e(str_starts_with($cover,'/')?$site.$cover:$cover) ?>"><?php endif ?><link rel="alternate" type="application/rss+xml" title="<?= $e($name) ?> RSS" href="<?= $e($href('/feed.xml')) ?>"><link rel="icon" href="<?= $e($asset('favicon.svg')) ?>"><link rel="stylesheet" href="<?= $e($asset('chronicle.css')) ?>?v=1.0.0"><script src="<?= $e($asset('chronicle.js')) ?>?v=1.0.0" defer></script><?php if($mode==='article'): $schema=['@context'=>'https://schema.org','@type'=>'Article','headline'=>$page['title'],'description'=>$description,'mainEntityOfPage'=>$canonical,'author'=>['@type'=>'Organization','name'=>$findTerm($page['author']??'','author')['title']??$name],'publisher'=>['@type'=>'Organization','name'=>$name]];if($cover&&!str_starts_with($cover,'data:'))$schema['image']=str_starts_with($cover,'/')?$site.$cover:$cover;foreach(['published_at'=>'datePublished','updated_at'=>'dateModified']as $field=>$property)if(!empty($page[$field])&&strtotime($page[$field])!==false)$schema[$property]=gmdate(DATE_ATOM,strtotime($page[$field].' UTC')); ?><script type="application/ld+json"><?= json_encode($schema,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP) ?></script><?php endif ?><?php if(($settings['font']??'')!=='system'): ?><link rel="preload" href="<?= $e($asset('assets/manrope.woff2')) ?>" as="font" type="font/woff2" crossorigin><?php endif ?><?php if(($settings['heading_font']??'')!=='georgia'): ?><link rel="preload" href="<?= $e($asset('assets/cormorant.woff2')) ?>" as="font" type="font/woff2" crossorigin><?php endif ?><style>:root{--c-accent:<?= $e($accent) ?>;--c-body:<?= ($settings['font']??'')==='system'?'system-ui':'ChronicleSans' ?>;--c-display:<?= ($settings['heading_font']??'')==='georgia'?'Georgia':'ChronicleDisplay' ?>}</style><?php if(($_GET['vitals']??'')==='1'): ?><script src="<?= $e(Content::asset('/themes/gallery/web-vitals.iife.js')) ?>" defer></script><script src="<?= $e($asset('vitals.js')) ?>" defer></script><?php endif ?></head>
