<div class="c-section-label"><span><?= $total ?> <?= $total%100>=11&&$total%100<=14?'материалов':([1=>'материал',2=>'материала',3=>'материала',4=>'материала'][$total%10]??'материалов') ?></span><span>Страница <?= $num ?> из <?= $pageCount ?></span></div><?php if(!$total): ?><section class="c-empty"><h2><?= $error?'Проверьте фильтры':($mode==='search'?'По вашему запросу ничего не найдено':'Публикаций пока нет') ?></h2><p>Измените условия или откройте все материалы издания.</p><a class="c-text-link" href="<?= $e($href('/articles/')) ?>">Все материалы ↗</a></section><?php else: ?><div class="c-archive-grid"><?php foreach(array_slice($list,($num-1)*9,9)as $p)$card($p); ?></div><?php if($pageCount>1): ?><nav class="c-pagination" aria-label="Страницы результатов"><?php for($i=1;$i<=$pageCount;$i++): ?><a href="<?= $e($href('/'.$path.'/',array_filter(['page'=>$i,'archive'=>$mode==='listing'&&($_GET['archive']??'')==='1'?'1':'','sort'=>$sort,'q'=>$q,'category'=>$category,'year'=>$year,'month'=>$month],fn($v)=>$v!==''))) ?>" <?= $num===$i?'aria-current="page"':'' ?>><?= $i ?></a><?php endfor ?></nav><?php endif;endif ?>
<?php elseif($page): ?>
<nav class="c-breadcrumb" aria-label="Хлебные крошки"><a href="<?= $e($href('/')) ?>">Главная</a><span>/</span><?php $cat=$findTerm($page['category']??'','category');if($cat): ?><a href="<?= $e($href('/category/'.$cat['slug'].'/')) ?>"><?= $e($cat['title']) ?></a><?php else: ?><span>Редакция</span><?php endif ?></nav><article class="c-story"><header class="c-story-heading"><span class="c-kicker"><?= $e($cat['title']??'Издание') ?> / <?= $mode==='article'?'Материал':'Информация' ?></span><h1><?= $e($page['title']) ?></h1><p class="c-deck"><?= $e($page['excerpt']??'') ?></p><?php if($mode==='article'): $meta($page); ?><span class="c-read-time"><?= max(1,(int)ceil(mb_strlen(strip_tags($reading))/1100)) ?> мин чтения</span><?php endif ?></header><?php if(!empty($page['cover'])): ?><figure class="c-story-cover"><?= $image($page,'(max-width:760px) calc(100vw - 40px), 1100px',true) ?><?php if(!empty($page['cover_alt'])): ?><figcaption><?= $e($page['cover_alt']) ?></figcaption><?php endif ?></figure><?php endif ?>
<div class="c-reading-layout"><aside class="c-reading-tools"><details class="c-toc" open><summary>В этом материале</summary><nav aria-label="Оглавление"><?php foreach($toc as $item): ?><a href="#<?= $e($item['id']) ?>"><?= $e($item['title']) ?></a><?php endforeach ?><?php if(!$toc): ?><a href="#reading-body">К тексту ↓</a><?php endif ?></nav></details><div class="c-enhancement" hidden><span class="c-kicker">Размер текста</span><div class="c-size-buttons"><button type="button" data-reading-size="smaller" aria-label="Уменьшить размер текста">А−</button><button type="button" data-reading-size="larger" aria-label="Увеличить размер текста">А+</button></div><?php if(!$privatePreview&&!$snapshot): ?><button type="button" class="c-share" data-copy-url="<?= $e($canonical) ?>">Скопировать ссылку ↗</button><input class="c-copy-fallback" aria-label="Ссылка на материал" value="<?= $e($canonical) ?>" readonly hidden><span class="c-copy-status" role="status" aria-live="polite"></span><?php endif ?></div></aside><div id="reading-body" class="c-prose"><?= $reading ?><?php if(($page['slug']??'')==='contacts'): if(!empty($settings['email'])): ?><p><a href="mailto:<?= $e($settings['email']) ?>"><?= $e($settings['email']) ?></a></p><?php endif;if(!empty($settings['phone'])): ?><p><a href="tel:<?= $e(preg_replace('/[^+0-9]/','',$settings['phone'])) ?>"><?= $e($settings['phone']) ?></a></p><?php endif;endif ?></div><aside class="c-margin-note"><span class="c-kicker">Читайте также</span><?php foreach(array_slice(array_values(array_filter($articles,fn($p)=>(int)$p['id']!==(int)$page['id'])),0,3)as $p): ?><a href="<?= $e($href('/'.$p['slug'].'/')) ?>"><?= $e($p['title']) ?></a><?php endforeach ?></aside></div></article>
<?php if($mode==='article'): $related=array_values(array_filter($articles,fn($p)=>(int)$p['id']!==(int)$page['id']&&($p['category']??'')===($page['category']??'')));if(!$related)$related=array_values(array_filter($articles,fn($p)=>(int)$p['id']!==(int)$page['id'])); ?><section class="c-home-section"><div class="c-section-label"><h2>Продолжить чтение</h2><a href="<?= $e($href('/articles/')) ?>">Все материалы ↗</a></div><div class="c-card-grid"><?php foreach(array_slice($related,0,3)as $p)$card($p); ?></div></section><?php endif ?>
<?php else: ?><section class="c-empty c-404"><span class="c-kicker">404 / Вне полосы</span><h1>Эта страница<br>не вошла в выпуск.</h1><p><?= $e($description) ?></p><a class="c-button" href="<?= $e($href('/search/')) ?>">Найти материал ↗</a><a class="c-text-link" href="<?= $e($href('/')) ?>">На главную</a></section><?php endif ?>
</main><footer class="c-footer"><div class="c-wrap"><div class="c-footer-top"><div><a class="c-footer-brand" href="<?= $e($href('/')) ?>"><?= $e($name) ?></a><p><?= $e($tagline) ?></p></div><div><span class="c-kicker">Продолжайте читать</span><p>Новые публикации<br>в вашей RSS-ленте.</p><a href="<?= $e($href('/feed.xml')) ?>">Открыть RSS ↗</a></div><nav aria-label="Меню в подвале"><a href="<?= $e($href('/articles/',['archive'=>1])) ?>">Архив</a><?php if($hasPage('about')): ?><a href="<?= $e($href('/about/')) ?>">О редакции</a><?php endif;if($hasPage('contacts')): ?><a href="<?= $e($href('/contacts/')) ?>">Контакты</a><?php endif ?><?= Journal::menu($settings['footer_menu']??[]) ?></nav></div><div class="c-colophon"><span>© <?= gmdate('Y') ?> <?= $e($name) ?></span><span>Контекст важнее шума.</span><a href="<?= $e($href('/search/')) ?>">Поиск по изданию ↗</a></div></div></footer><div class="c-reading-progress" aria-hidden="true"><span></span></div></body></html>
